import{_ as e,b as a,e as d,a8 as i}from"./chunks/framework.CumEd6mW.js";const m=JSON.parse('{"title":"TBitmap32","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TBitmap32","kind":"Class","declaration":"TBitmap32 = class(TCustomBitmap32)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomMap","TCustomBitmap32","TBitmap32"],"summary":"Primary 32-bit ARGB bitmap class in Graphics32, providing VCL/LCL Canvas, GDI device context (HDC), and OS surface handle bindings.","title":"TBitmap32","date":1789041987000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TBitmap32/index.md","filePath":"api/GR32/Classes/TBitmap32/index.md","lastUpdated":1789041987000,"timestamp":1789041987000,"datetime":"2026-09-10T12:06:27.000Z"}'),r={name:"api/GR32/TBitmap32/index.md"};function n(o,t,s,c,p,h){return a(),d("div",null,[...t[0]||(t[0]=[i('<h2 id="declaration" tabindex="-1">Declaration <a class="header-anchor" href="#declaration" aria-label="Permalink to &quot;Declaration&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TBitmap32 = </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(TCustomBitmap32)</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TBitmap32</code> is the standard concrete 32-bit ARGB bitmap implementation in Graphics32. It inherits all core pixel buffer management, sub-pixel sampling, drawing primitives, blending modes, and resamplers from <a href="/api/GR32/TCustomBitmap32/">TCustomBitmap32</a>.</p><p>In addition, <code>TBitmap32</code> integrates with host OS graphics frameworks (VCL on Windows, LCL on cross-platform GUI toolkits) by exposing a standard VCL/LCL <code>Canvas</code>, device context (<code>HDC</code>), GDI bitmap surface handle (<code>Handle</code>), <code>Font</code> property for text rendering, and GDI drawing routines (<code>TileTo</code>, HDC <code>Draw</code> / <code>DrawTo</code> overloads).</p><h2 id="constructors-destructors" tabindex="-1">Constructors &amp; Destructors <a class="header-anchor" href="#constructors-destructors" aria-label="Permalink to &quot;Constructors &amp; Destructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/GR32/TBitmap32/Create">Create</a></td><td>Inherited constructor that instantiates a new <code>TBitmap32</code> bitmap instance.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/GR32/TBitmap32/DeleteCanvas">DeleteCanvas</a></td><td>Frees and releases the internal VCL/LCL <code>TCanvas</code> instance allocated for this bitmap.</td></tr><tr><td><a href="/api/GR32/TBitmap32/Draw">Draw</a></td><td>Draws a source bitmap, sub-rectangle, or GDI DC onto this bitmap.</td></tr><tr><td><a href="/api/GR32/TBitmap32/DrawTo">DrawTo</a></td><td>Draws this bitmap onto a destination bitmap or GDI device context (HDC).</td></tr><tr><td><a href="/api/GR32/TBitmap32/GetPlatformBackendClass">GetPlatformBackendClass</a></td><td>Returns the platform-default backend class used for surface management.</td></tr><tr><td><a href="/api/GR32/TBitmap32/RenderText">RenderText</a></td><td>Renders anti-aliased text directly into the bitmap buffer using specified color.</td></tr><tr><td><a href="/api/GR32/TBitmap32/TextExtent">TextExtent</a></td><td>Calculates the pixel width and height dimensions of a text string when rendered using current Font.</td></tr><tr><td><a href="/api/GR32/TBitmap32/TextHeight">TextHeight</a></td><td>Returns the height in pixels of a text string when rendered using current Font.</td></tr><tr><td><a href="/api/GR32/TBitmap32/Textout">Textout</a></td><td>Renders text string onto the bitmap surface at specified coordinates or bounding rectangle using the current Font.</td></tr><tr><td><a href="/api/GR32/TBitmap32/TextWidth">TextWidth</a></td><td>Returns the width in pixels of a text string when rendered using current Font.</td></tr><tr><td><a href="/api/GR32/TBitmap32/TileTo">TileTo</a></td><td>Tiles a source bitmap sub-rectangle repeatedly onto a target GDI device context (HDC).</td></tr><tr><td><a href="/api/GR32/TBitmap32/UpdateFont">UpdateFont</a></td><td>Notifies the backend that font property changes have occurred and updates font settings.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/GR32/TBitmap32/BitmapInfo">BitmapInfo</a></td><td><code>TBitmapInfo</code></td><td>Public</td><td>Read-only GDI bitmap header information structure.</td></tr><tr><td><a href="/api/GR32/TBitmap32/Canvas">Canvas</a></td><td><code>TCanvas</code></td><td>Public</td><td>VCL/LCL drawing canvas bound to the bitmap&#39;s device context (HDC).</td></tr><tr><td><a href="/api/GR32/TBitmap32/CanvasAllocated">CanvasAllocated</a></td><td><code>boolean</code></td><td>Public</td><td>Indicates whether a VCL/LCL <code>TCanvas</code> instance is currently allocated for this bitmap.</td></tr><tr><td><a href="/api/GR32/TBitmap32/Font">Font</a></td><td><code>TFont</code></td><td>Public</td><td>Font instance used for canvas text rendering operations.</td></tr><tr><td><a href="/api/GR32/TBitmap32/Handle">Handle</a></td><td><code>HBITMAP</code></td><td>Public</td><td>OS GDI bitmap surface handle.</td></tr><tr><td><a href="/api/GR32/TBitmap32/HDC">HDC</a></td><td><code>HDC</code></td><td>Public</td><td>OS GDI device context handle bound to pixel buffer surface.</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/GR32/TBitmap32/OnHandleChanged">OnHandleChanged</a></td><td><code>TNotifyEvent</code></td><td>Fired when the OS GDI bitmap surface handle (<code>Handle</code>) changes or is re-allocated.</td></tr></tbody></table>',13)])])}const u=e(r,[["render",n]]);export{m as __pageData,u as default};
